from taf.ul.bts_components import Smod
from taf.rfrl.procedures.resources.python.testline.TestLine import TestLine


class SwStreamSingleton(object):
    """ Singleton class for getting and storing SW stream name for whole test suite duration """

    _instance = None
    _sw_stream = None
    _master = False

    def __new__(cls):
        if cls._instance is None:
            cls._instance = super(SwStreamSingleton, cls).__new__(cls)
        return cls._instance

    def get_sw_stream(self, translate_master=False, device='GNB'):
        """
        Gets software stream

        :param translate_master: If true translates prefix only for master.
        :param device: can be GNB or ENB, gives information whether sw_stream should be taken from gNB or eNB.
                       GNB by default.
        :type device: str
        :return: Returns stream of given software

                    e.g:
                        Sw on bts: 5G21A_0.800.xxx

                        If translate is True:
                            output:  'master'

                        otherwise:
                            output:  '5G21A'
        :rtype: str
        """
        if self._sw_stream is None:
            self._sw_stream, self._master = self._get_sw_stream(device=device)

        if translate_master and self._master:
            return self._translate()
        return self._sw_stream

    def _translate(self):
        if "SBTS" in self._sw_stream:
            return "SBTS_master"
        return "master"

    @staticmethod
    def _get_sw_stream(device):
        smod = Smod()
        credentials = TestLine().get_ssh_credentials(bts_type=device)
        try:
            smod.connect_to(address=credentials['host'],
                            username=credentials['username'],
                            password=credentials['password']
                            )

            master = False
            sw_version = smod.get_sw_version_as_list_from_targetbd()
            if (sw_version[2] == "" and sw_version[3] == "800") or sw_version[2] in ["9999", "9990"]:
                master = True

            return sw_version[0], master

        finally:
            smod.close_connection()
